/usr/bin/python3 -B - <<'PY'
import json
import os
import stat

expected = {'authorization.md', 'execution-report.md', 'results.json', 'commands.json', 'environment.json', 'verification.json'}
directory_fd = os.open('.', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
try:
    for part in ('artifacts', 'evidence', 'TI3_A'):
        next_fd = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=directory_fd)
        os.close(directory_fd)
        directory_fd = next_fd
    names = set(os.listdir(directory_fd))
    print(json.dumps({'file_count': len(names), 'files': sorted(names), 'exact_allowlist': names == expected}))
    if names != expected:
        raise RuntimeError('TI3_A file allowlist divergence')
    for name in sorted(expected):
        fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW, dir_fd=directory_fd)
        try:
            if not stat.S_ISREG(os.fstat(fd).st_mode):
                raise RuntimeError('Not a regular file: ' + name)
            with os.fdopen(fd, 'r', encoding='utf-8', closefd=False) as stream:
                content = stream.read()
            print('\nFILE ' + name)
            if name.endswith('.json'):
                document = json.loads(content)
                print('JSON_VALID=true')
                if name == 'commands.json':
                    for key, value in document.items():
                        if isinstance(value, list):
                            print(json.dumps({'key': key, 'count': len(value), 'entry_keys': [list(x.keys()) if isinstance(x, dict) else type(x).__name__ for x in value]}, ensure_ascii=False))
                        else:
                            print(json.dumps({key: value}, ensure_ascii=False))
                else:
                    print(content)
            else:
                print(content)
        finally:
            os.close(fd)
finally:
    os.close(directory_fd)
PY
